import re
from decimal import Decimal

MAX_CENTS = 100000000  # 1000000.00
_MAX_AMOUNT = Decimal("1000000.00")
_PLAIN_DECIMAL = re.compile(r"[+-]?(?:[0-9]+\.?[0-9]*|\.[0-9]+)")


def amount_cents(value):
    """Validate an amount and return it as a positive integer number of cents.

    Works on exact integer/Decimal arithmetic only, so the global decimal
    context is never read or changed and the input is never mutated.
    """
    if isinstance(value, bool):
        raise ValueError("boolean is not a valid amount")
    if isinstance(value, Decimal):
        number = value
    elif isinstance(value, int):
        number = Decimal(value)
    elif isinstance(value, str):
        if _PLAIN_DECIMAL.fullmatch(value) is None:
            raise ValueError(f"not a plain decimal string: {value!r}")
        number = Decimal(value)
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")

    if not number.is_finite():
        raise ValueError("amount must be finite")
    if number <= 0:
        raise ValueError("amount must be positive")
    if number > _MAX_AMOUNT:
        raise ValueError("amount must be at most 1000000.00")
    if number.adjusted() < -2:
        # Positive and below one cent: not exactly representable in cents.
        raise ValueError("amount is not exactly representable in cents")

    _, digits, exponent = number.as_tuple()
    coefficient = int("".join(map(str, digits)))
    if exponent < -2:
        # Only trailing zeros may fall beyond the cent position.
        coefficient, remainder = divmod(coefficient, 10 ** (-2 - exponent))
        if remainder:
            raise ValueError("amount is not exactly representable in cents")
        return coefficient
    return coefficient * 10 ** (exponent + 2)


def cents_to_decimal(cents):
    """Return a non-negative integer number of cents as a Decimal with exponent -2."""
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


def parse_amount(value):
    return cents_to_decimal(amount_cents(value))


def format_amount(value):
    return format(value, ".2f")
